WITH RECURSIVE x9 AS (SELECT x7.v4254 * 0 AS x10 UNION ALL SELECT x7.v4253 + 1 FROM x11 WHERE x7.v4253 = 0) SELECT x7.v4254, x7.v4254, CONCAT_WS(REPEAT(CONCAT(x7.v4254 COLLATE utf8mb4_roman_ci), -2), CONCAT_WS('', CONCAT(HEX(STRCMP('9', x7.v4254))), (CASE 42 WHEN x7.v4254 THEN x7.v4253 ELSE x7.v4254 END))) AS x4, x7.v4253 FROM v4252 AS x7 WHERE x7.v4253 IN (CAST('01:01:01' AS TIME), CAST('02:02:02' AS TIME), CAST('05:05:05' AS TIME))